 * Parsing of an election description into candidates and ballots.
 */

const NAME = /^[A-Za-z0-9_-]+$/

export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ParseError'
  }
}

function fail(message) {
  throw new ParseError(message)
}

function failAt(lineNumber, message) {
  fail(`line ${lineNumber}: ${message}`)
}

/**
 * Splits the raw input into physical lines, dropping the empty tail that a
 * trailing newline leaves behind.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parses an election. Returns { candidates, ballots } where candidates is the
 * declared order and each ballot is { count, ranking }.
 */
export function parseElection(text) {
  const lines = splitLines(text)
  let candidates = null
  const declared = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i += 1) {
    const lineNumber = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        failAt(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const names = words.slice(1)
      if (names.length === 0) failAt(lineNumber, 'expected candidates <name>...')
      for (const name of names) {
        if (!NAME.test(name)) failAt(lineNumber, `invalid candidate name ${name}`)
        if (declared.has(name)) failAt(lineNumber, `candidate ${name} is declared twice`)
        declared.add(name)
      }
      candidates = names
    } else if (directive === 'ballot') {
      if (candidates === null) {
        failAt(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (words.length < 3) failAt(lineNumber, 'expected ballot <count> <candidate>...')
      const count = words[1]
      if (!/^[1-9][0-9]*$/.test(count)) failAt(lineNumber, 'count must be a positive integer')
      const ranking = words.slice(2)
      const seen = new Set()
      for (const name of ranking) {
        if (!declared.has(name)) failAt(lineNumber, `unknown candidate ${name}`)
        if (seen.has(name)) failAt(lineNumber, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(count), ranking })
    } else {
      failAt(lineNumber, `unknown directive ${directive}`)
    }
  }

  if (candidates === null) fail('no candidates')
  return { candidates, ballots }
}
