{"file_path":"src/count.js","content":"/**
 * The instant-runoff count itself.
 */

/**
 * Runs the election. Returns { rounds, winner } where each round is
 * { counts: Map<name, votes>, exhausted, eliminated } and winner is a name or
 * null when no candidate ever reached the majority.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((name) => [name, []]))
  const rounds = []

  for (;;) {
    const counts = new Map()
    for (const name of candidates) if (continuing.has(name)) counts.set(name, 0)
    let exhausted = 0
    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) exhausted += ballot.count
      else counts.set(choice, counts.get(choice) + ballot.count)
    }
    for (const [name, votes] of counts) history.get(name).push(votes)

    const round = { counts, exhausted, eliminated: null }
    rounds.push(round)

    let active = 0
    for (const votes of counts.values()) active += votes
    if (active === 0) return { rounds, winner: null }

    let leader = null
    for (const [name, votes] of counts) {
      if (leader === null || votes > counts.get(leader)) leader = name
    }
    if (counts.get(leader) * 2 > active) return { rounds, winner: leader }

    const loser = pickLoser(counts, history)
    round.eliminated = loser
    continuing.delete(loser)
  }
}

/**
 * Chooses the candidate to eliminate: fewest votes this round, ties broken by
 * comparing the whole count history from the first round onwards, and finally
 * by the name that sorts last.
 */
function pickLoser(counts, history) {
  let fewest = Infinity
  for (const votes of counts.values()) if (votes < fewest) fewest = votes
  let tied = [...counts.keys()].filter((name) => counts.get(name) === fewest)

  const depth = history.get(tied[0]).length
  for (let round = 0; round < depth && tied.length > 1; round += 1) {
    let least = Infinity
    for (const name of tied) {
      const votes = history.get(name)[round]
      if (votes < least) least = votes
    }
    tied = tied.filter((name) => history.get(name)[round] === least)
  }

  let loser = tied[0]
  for (const name of tied) if (name > loser) loser = name
  return loser
}
"}

