{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { ParseError, parseElection } from './parse.js'
import { runElection } from './count.js'

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function formatRound(round, index) {
  const names = [...round.counts.keys()].sort((a, b) => {
    const difference = round.counts.get(b) - round.counts.get(a)
    if (difference !== 0) return difference
    return a < b ? -1 : a > b ? 1 : 0
  })
  const parts = names.map((name) => `${name}=${round.counts.get(name)}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${index + 1}: ${parts.join(' ')}\n`
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'rounds' && argv[0] !== 'tally')) {
    die('usage: cli.js rounds|tally')
  }
  const mode = argv[0]

  let election
  try {
    election = parseElection(readStdin())
  } catch (error) {
    if (error instanceof ParseError) die(error.message)
    throw error
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)
  let out = ''
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      out += formatRound(round, index)
      if (round.eliminated !== null) out += `eliminated ${round.eliminated}\n`
    })
  } else {
    out += `rounds ${rounds.length}\n`
  }
  out += winner === null ? 'no winner\n' : `winner ${winner}\n`
  process.stdout.write(out)
}

main()
"}

